 * 실행 계정 = SCM_MGR (전체 F5 · 반복 실행 안전)
 */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 코드 객체 — 전부 VALID */
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PKG_SCP0100') ORDER BY 1, 2;

/* 2) 컴파일 오류 — 0건 */
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_SCP0100') ORDER BY NAME, TYPE, SEQUENCE;

/* 3) GTT 구조 — 0건(사내와 다른 GTT 가 있으면 행) */
