    UNION ALL SELECT 'GT_SCP0100_ALL_MEASURE_UI' T, 'DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;CELL_CF|NUMBER|0|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y;CODE|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;DISPLAY_SEQ|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
