    UNION ALL SELECT 'GT_SCP0100_DAYCOLS' T, 'YYYYPW_NAME|VARCHAR2|20|||Y;YYYYPW|VARCHAR2|20|||Y;SORT_ORDER_NO|VARCHAR2|20|||Y' S FROM DUAL
