    UNION ALL SELECT 'GT_SCP0100_FINAL' T, 'DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|200|||Y;OPERATION_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;CELL_CF|NUMBER|0|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y;CELL_GROUP_SORT_ORDER_NO|NUMBER|0|||Y;CODE|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;DISPLAY_SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_LINE' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;MEASURE|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_MEASURE' T, 'MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_MEASURE1' T, 'MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_MEASURE2' T, 'MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_MEASURE3' T, 'MEASURE_UI|VARCHAR2|200|||Y;MEASURE_NAME|VARCHAR2|500|||Y;MEASURE_GROUP|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_OPERATION' T, 'DIVISION_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|200|||Y;FLOW_ID|VARCHAR2|50|||Y;OPERATION|VARCHAR2|50|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_PRODUCTLEVEL' T, 'DIVISION_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|200|||Y;FLOW_ID|VARCHAR2|50|||Y;BIZ_TYPE|VARCHAR2|50|||Y;GROUP_CODE6|VARCHAR2|200|||Y;GROUP_CODE7|VARCHAR2|200|||Y;GROUP_CODE5|VARCHAR2|200|||Y;BASIC_FINISHED_PRODUCT|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_AUTO' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_CELL_GROUP' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_CELL_GROUP_DETAIL' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_DETAIL' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;INCOTERMS|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_PRODUCT_LEVEL1' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_PRODUCT_LEVEL2' T, 'YYYYPW|VARCHAR2|20|||Y;DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_QTY_PRODUCT_LEVEL3' T, 'YYYYPW|VARCHAR2|200|||Y;DIVISION_ID|VARCHAR2|200|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;MEASURE_UI|VARCHAR2|200|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_RAW' T, 'PLAN_START_YYYYMMDD|VARCHAR2|8|||Y;DIVISION_ID|VARCHAR2|50|||Y;YYYYPW|VARCHAR2|20|||Y;ITEM_ID|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;MEASURE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;REP_CELL_ITEM_ID|VARCHAR2|200|||Y;CELL_GROUP|VARCHAR2|200|||Y;CELL_GROUP_SORT_ORDER_NO|NUMBER|0|||Y;QTY|NUMBER|0|||Y;FROM_BOH_QTY|NUMBER|0|||Y;TO_BOH_QTY|NUMBER|0|||Y;CELL_CF|NUMBER|0|||Y;ATTRIBUTE3|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;FLOW_ID|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;OPERATION_NAME|VARCHAR2|200|||Y;CELL_QTY|NUMBER|0|||Y;INV_SORT|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_RAW_CELL_CF' T, 'DIVISION_ID|VARCHAR2|50|||Y;CELL_GROUP|VARCHAR2|200|||Y;OPERATION_GROUP|VARCHAR2|50|||Y;OPERATION_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|200|||Y;TO_SITE|VARCHAR2|200|||Y;FROM_SITE|VARCHAR2|200|||Y;INCOTERMS|VARCHAR2|200|||Y;PRODUCT_LEVEL1|VARCHAR2|200|||Y;PRODUCT_LEVEL2|VARCHAR2|200|||Y;PRODUCT_LEVEL3|VARCHAR2|200|||Y;MEASURE|VARCHAR2|200|||Y;VARIOUS_KEY|VARCHAR2|500|||Y;CELL_CF|NUMBER|0|||Y;PLAN_TYPE|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_TRANSPORT_MODE_CODE' T, 'CODE|VARCHAR2|200|||Y;NAME|VARCHAR2|500|||Y;DISPLAY_SEQ|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0100_USER_COLS' T, 'COLUMN_NAME|VARCHAR2|200|||Y;COLUMN_LABEL_NAME|VARCHAR2|500|||Y;SORT_ORDER_NO|NUMBER|0|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0100' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'P_SCP0100_CALENDAR_GET' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0100_GET' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0100_PLAN_DATE_GET' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0100_SITE_GET' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0100' MNU_ID, 'calendar' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'planDate' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'MEASURE_SELECT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'searchLevel' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'searchLevelDetail' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0100' MNU_ID, 'site' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S;
SELECT 'SCM_ADM_PROC_M' AS TBL, '화면 PKG 프로시저 파라미터' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_PROC_M T WHERE NVL(TO_CHAR(T.PROC_NM), '~') = NVL(TO_CHAR(S.PROC_NM), '~') AND NVL(TO_CHAR(T.COL_NM), '~') = NVL(TO_CHAR(S.COL_NM), '~') AND NVL(TO_CHAR(T.COL_TP_CD), '~') = NVL(TO_CHAR(S.COL_TP_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'O_RESULT_CURSOR' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'bucket' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'cellGroup' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'chkAs' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'chkCellQty' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'debugMode' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'divisionId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'fromSite' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'fromYyyymmdd' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'itemId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'nickName' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'o_rc1' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'planStartYyyymmdd' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'planType' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'project' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'searchLevel' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'toSite' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'toYyyymmdd' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_GLOBAL_PSI_REPORT' PROC_NM, 'userId' COL_NM, 'IN' COL_TP_CD FROM DUAL
