SELECT 'SCM_ADM_CMBO_SQL_M' AS TBL, '콤보 SQL(공용) — 없을 때만' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'BUCKET_TYPE_CODE' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CELL_GROUP' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'Division_SCP' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'Measure' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'PLAN_END_DATE_REPORT' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'PlanType1_SCP_ALL' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL) S;

/* 5) 클라우드에만 있는 화면 META 행(사내에 없음) — 참고. 지우지 않음 */
SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'SCP0100' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT CAST(NULL AS VARCHAR2(4000)) API_ID FROM DUAL WHERE 1 = 0) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
